{"sql":"WITH counts AS (
  SELECT g.GenreId, g.Name, COUNT(t.TrackId) AS track_count
  FROM Genre g
  LEFT JOIN Track t ON t.GenreId = g.GenreId
  GROUP BY g.GenreId, g.Name
)
SELECT Name, track_count
FROM counts
WHERE track_count = (SELECT MAX(track_count) FROM counts);
"}

